import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Matrix-vector multiplication: C (M,1) = A (M,K) * B (K,1)
// One thread block per output row. Threads stride over K with float4
// vectorized loads, accumulate a local partial dot product, then do a
// warp + shared-memory block reduction.
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K, int kChunk) {
    // Split-K GEMV with a taller 8-row CTA tile. Each thread reuses every
    // float4 B fragment across eight independent row streams, increasing
    // memory-level parallelism while keeping the same split-K reduction.
    int tid = threadIdx.x;
    int lane = tid & 31;
    int wid  = tid >> 5;
    __shared__ float shared[8][32];
    int kStart = blockIdx.y * kChunk;
    if (kStart >= K) return;
    int kEnd = min(K, kStart + kChunk);
    int row0 = blockIdx.x * 8;
    const float* a[8];
    const float4* a4[8];
    bool has[8];
    float sum[8];
    #pragma unroll
    for (int r = 0; r < 8; ++r) {
        int row = row0 + r;
        has[r] = row < M;
        a[r] = has[r] ? (A + (long long)row * (long long)K)
                      : (A + (long long)row0 * (long long)K);
        a4[r] = reinterpret_cast<const float4*>(a[r]);
        sum[r] = 0.0f;
    }
    // kChunk is a multiple of 4, so every split stays float4-aligned.
    int i4start = kStart >> 2;
    int i4end = kEnd >> 2;
    const float4* b4 = reinterpret_cast<const float4*>(B);
    for (int i = i4start + tid; i < i4end; i += blockDim.x) {
        float4 bv = b4[i];
        #pragma unroll
        for (int r = 0; r < 8; ++r) {
            if (has[r]) {
                float4 av = a4[r][i];
                sum[r] += av.x * bv.x + av.y * bv.y + av.z * bv.z + av.w * bv.w;
            }
        }
    }
    // Handle any tail elements (K not divisible by 4) in the final split.
    for (int i = (i4end << 2) + tid; i < kEnd; i += blockDim.x) {
        float bv = B[i];
        #pragma unroll
        for (int r = 0; r < 8; ++r) {
            if (has[r]) sum[r] += a[r][i] * bv;
        }
    }
    // Warp-level reduction
    #pragma unroll
    for (int r = 0; r < 8; ++r) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum[r] += __shfl_down_sync(0xffffffffu, sum[r], offset);
        }
    }
    if (lane == 0) {
        #pragma unroll
        for (int r = 0; r < 8; ++r) {
            shared[r][wid] = has[r] ? sum[r] : 0.0f;
        }
    }
    __syncthreads();
    int numWarps = (blockDim.x + 31) >> 5;
    if (wid == 0) {
        #pragma unroll
        for (int r = 0; r < 8; ++r) {
            sum[r] = (lane < numWarps) ? shared[r][lane] : 0.0f;
        }
        #pragma unroll
        for (int r = 0; r < 8; ++r) {
            for (int offset = 16; offset > 0; offset >>= 1) {
                sum[r] += __shfl_down_sync(0xffffffffu, sum[r], offset);
            }
        }
        if (lane == 0) {
            #pragma unroll
            for (int r = 0; r < 8; ++r) {
                if (has[r]) atomicAdd(&C[row0 + r], sum[r]);
            }
        }
    }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0) && B.size(1) == 1, "Shape mismatch");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    int M = A_c.size(0);
    int K = A_c.size(1);
    auto C = torch::zeros({M, 1}, A_c.options());
    int threads = 256;
    int tiles = (M + 7) / 8;
    int device = 0;
    cudaGetDevice(&device);
    int smCount = 0;
    cudaDeviceGetAttribute(&smCount, cudaDevAttrMultiProcessorCount, device);
    int maxBlocksPerSm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&maxBlocksPerSm, matvec_kernel, threads, 0);
    if (smCount < 1) smCount = 1;
    if (maxBlocksPerSm < 1) maxBlocksPerSm = 1;
    long long fullWave = (long long)smCount * (long long)maxBlocksPerSm;
    // Split-K factor: grow the grid to about four full resident waves of
    // evenly sized CTAs so all SMs stay busy and the launch tail disappears.
    int splits = 1;
    if ((long long)tiles < 4LL * fullWave) {
        long long wanted = (4LL * fullWave + tiles - 1) / tiles;
        splits = wanted > 32 ? 32 : (int)wanted;
    }
    int kChunk = (((K + splits - 1) / splits) + 3) & ~3;
    splits = (K + kChunk - 1) / kChunk;
    dim3 grid(tiles, splits);
    matvec_kernel<<<grid, threads>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, kChunk);
    return C;
